impl Drop for BatchProcessor {
    /// Best effort: marks the processor closed so the worker exports what is queued and exits.
    fn drop(&mut self) {
        self.shared.lock().closed = true;
        self.shared.wake.notify_one();
        self.shared.notify_space();
    }
}

impl Shared {
    /// Locks the state, recovering from poisoning (callbacks never run under the lock).
    fn lock(&self) -> MutexGuard<'_, State> {
        self.state.lock().unwrap_or_else(|e| e.into_inner())
    }

    fn notify_space(&self) {
        self.space.notify_all();
        self.space_async.notify_waiters();
    }

    fn block_for_space<'a>(&'a self, st: MutexGuard<'a, State>) -> Admit<'a> {
        let wait = |mut st: MutexGuard<'a, State>| {
            let deadline = Instant::now() + self.opts.export_timeout;
            loop {
                if st.closed {
                    return Admit::Closed;
                }
                if st.queue.len() < self.opts.max_queue_size {
                    return Admit::Room(st);
                }
                let now = Instant::now();
                if now >= deadline {
                    return Admit::Full;
                }
                st = self
                    .space
                    .wait_timeout(st, deadline - now)
                    .unwrap_or_else(|e| e.into_inner())
                    .0;
            }
        };
        match Handle::try_current().map(|h| h.runtime_flavor()) {
            // Blocking here would stall the only thread, including the worker.
            Ok(RuntimeFlavor::CurrentThread) => Admit::Full,
            // Other runtime threads keep running the worker; the wait is bounded.
            _ => wait(st),
        }
    }

    fn admit(&self, admit: Admit<'_>, record: LogRecord, bytes: usize) -> bool {
        let mut st = match admit {
            Admit::Room(st) => st,
            Admit::Full => {
                self.dropped_records(&[record], DropReason::QueueFull);
                return false;
            }
            Admit::Closed => {
                self.dropped_records(&[record], DropReason::Shutdown);
                return false;
            }
        };
        let evicted = if st.queue.len() >= self.opts.max_queue_size {
            st.queue
                .pop_front()
                .inspect(|old| st.queued_bytes -= old.bytes)
        } else {
            None
        };
        st.queue.push_back(Item { record, bytes });
        st.queued_bytes += bytes;
        st.accepted_total += 1;
        let wake = st.queue.len() >= self.opts.max_batch_size
            || st.queued_bytes >= self.opts.max_batch_bytes;
        drop(st);
        if let Some(old) = evicted {
            self.processed.send_modify(|p| *p += 1);
            self.dropped_records(&[old.record], DropReason::QueueFull);
        }
        if wake {
            self.wake.notify_one();
        }
        true
    }

    fn dropped_records(&self, records: &[LogRecord], reason: DropReason) {
        self.dropped
            .fetch_add(records.len() as u64, Ordering::Relaxed);
        if let Some(cb) = &self.opts.on_drop {
            let _ = catch_unwind(AssertUnwindSafe(|| cb(records, reason)));
        }
    }

    fn report_error(&self, error: &Error, records: &[LogRecord]) {
        if let Some(cb) = &self.opts.on_error {
            let _ = catch_unwind(AssertUnwindSafe(|| cb(error, records)));
        }
    }

    /// Drops the in-flight batch of an aborted worker and everything queued.
    fn drop_remaining(&self) {
        let records: Vec<LogRecord> = {
            let mut st = self.lock();
            st.queued_bytes = 0;
            let in_flight = st.in_flight.take();
            let mut records: Vec<LogRecord> =
                in_flight.map(|b| b.as_ref().clone()).unwrap_or_default();
            records.extend(st.queue.drain(..).map(|i| i.record));
            records
        };
        if records.is_empty() {
            return;
        }
        self.processed.send_modify(|p| *p += records.len() as u64);
        self.dropped_records(&records, DropReason::Shutdown);
    }

    /// Takes the next batch when one is due; `None` when the worker should wait.
    fn next_batch(&self, due: bool) -> Option<Arc<Vec<LogRecord>>> {
        let mut st = self.lock();
        let flushing = *self.processed.borrow() < st.flush_target;
        let full = st.queue.len() >= self.opts.max_batch_size
            || st.queued_bytes >= self.opts.max_batch_bytes;
        if st.queue.is_empty() || !(due || flushing || full || st.closed) {
            return None;
        }
        let mut batch = Vec::new();
        let mut bytes = 0usize;
        while let Some(item) = st.queue.front() {
            let over = bytes + item.bytes > self.opts.max_batch_bytes;
            if batch.len() >= self.opts.max_batch_size || (!batch.is_empty() && over) {
                break;
            }
            bytes += item.bytes;
            let item = st.queue.pop_front().expect("front exists");
            batch.push(item.record);
        }
        st.queued_bytes -= bytes;
        let batch = Arc::new(batch);
        st.in_flight = Some(Arc::clone(&batch));
        drop(st);
        self.notify_space();
        Some(batch)
    }

    async fn export_batch(&self, records: Arc<Vec<LogRecord>>) {
        let n = records.len() as u64;
        let opts = ExportOptions::new(self.opts.gzip);
        let mut attempt = 0u32;
        loop {
            let res = tokio::time::timeout(
                self.opts.export_timeout,
                self.exporter.export(&records, opts),
            )
            .await
            .unwrap_or_else(|_| {
                Err(Error::timeout(format!(
                    "log export timed out after {:?}",
                    self.opts.export_timeout
                )))
            });
            match res {
                Ok(r) => {
                    let accepted = (r.accepted as u64).min(n);
                    self.sent.fetch_add(accepted, Ordering::Relaxed);
                    let failed = n - accepted;
                    self.failed.fetch_add(failed, Ordering::Relaxed);
                    match r.error {
                        Some(e) => self.report_error(&e, &records),
                        None if failed > 0 => self.report_error(
                            &Error::validation(format!(
                                "{failed} of {n} log records were rejected"
                            )),
                            &records,
                        ),
                        None => {}
                    }
                }
                Err(e) if e.is_retryable() && attempt < self.opts.max_export_retries => {
                    attempt += 1;
                    self.retries.fetch_add(1, Ordering::Relaxed);
                    let backoff = self.opts.retry_backoff * (1u32 << (attempt - 1).min(16));
                    tokio::time::sleep(backoff).await;
                    continue;
                }
                Err(e) => {
                    self.failed.fetch_add(n, Ordering::Relaxed);
                    self.report_error(&e, &records);
                    if let Some(cb) = &self.opts.on_drop {
                        let _ = catch_unwind(AssertUnwindSafe(|| {
                            cb(&records, DropReason::ExportFailed)
                        }));
                    }
                }
            }
            break;
        }
        self.lock().in_flight = None;
        self.processed.send_modify(|p| *p += n);
    }
}

async fn run_worker(shared: Arc<Shared>) {
    let interval = shared.opts.flush_interval;
    let mut deadline = tokio::time::Instant::now() + interval;
    loop {
        let due = tokio::time::Instant::now() >= deadline;
        if let Some(batch) = shared.next_batch(due) {
            shared.export_batch(batch).await;
            continue;
        }
        if due {
            deadline = tokio::time::Instant::now() + interval;
        }
        {
            let st = shared.lock();
            if st.closed && st.queue.is_empty() {
                return;
            }
        }
        tokio::select! {
            _ = shared.wake.notified() => {}
            _ = tokio::time::sleep_until(deadline) => {}
        }
    }
}
